$MAVEN_REPO/jakarta/ws/rs/jakarta.ws.rs-api/3.1.0/jakarta.ws.rs-api-3.1.0.jar,\
$MAVEN_REPO/org/glassfish/jersey/core/jersey-common/3.1.2/jersey-common-3.1.2.jar,\
$MAVEN_REPO/jakarta/annotation/jakarta.annotation-api/2.1.1/jakarta.annotation-api-2.1.1.jar,\
